import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.7He2WLS4.js";const p=JSON.parse('{"title":"Tutorials & Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":1772297611000}'),n={name:"guides/index.md"};function a(s,i,l,g,u,c){return t(),o("div",null,[...i[0]||(i[0]=[r('<h1 id="tutorials-guides" tabindex="-1">Tutorials &amp; Guides <a class="header-anchor" href="#tutorials-guides" aria-label="Permalink to &quot;Tutorials &amp; Guides&quot;">​</a></h1><p>Welcome to the NectoProxy tutorials section. These step-by-step guides walk you through real-world debugging scenarios, from mocking APIs to debugging mobile apps to simulating poor network conditions.</p><h2 id="available-tutorials" tabindex="-1">Available Tutorials <a class="header-anchor" href="#available-tutorials" aria-label="Permalink to &quot;Available Tutorials&quot;">​</a></h2><h3 id="mocking-apis" tabindex="-1"><a href="./mocking-apis.html">Mocking APIs</a> <a class="header-anchor" href="#mocking-apis" aria-label="Permalink to &quot;[Mocking APIs](./mocking-apis)&quot;">​</a></h3><p><strong>Difficulty:</strong> Beginner | <strong>Time:</strong> 10 minutes</p><p>Build a frontend without a backend. Learn how to create mock rules that return custom JSON responses for any URL pattern, letting you develop and test your application against simulated API endpoints.</p><p><strong>What you will learn:</strong></p><ul><li>Creating Mock rules in the Rules panel</li><li>Returning custom JSON, status codes, and headers</li><li>Mocking different HTTP methods (GET, POST, PUT, DELETE)</li><li>Simulating error responses and slow APIs</li></ul><hr><h3 id="debugging-mobile-apps" tabindex="-1"><a href="./debugging-mobile.html">Debugging Mobile Apps</a> <a class="header-anchor" href="#debugging-mobile-apps" aria-label="Permalink to &quot;[Debugging Mobile Apps](./debugging-mobile)&quot;">​</a></h3><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 15 minutes</p><p>Capture and inspect HTTP/HTTPS traffic from iOS and Android devices. Learn how to configure your phone to route traffic through NectoProxy and install the CA certificate for HTTPS inspection.</p><p><strong>What you will learn:</strong></p><ul><li>Binding NectoProxy to all network interfaces</li><li>Configuring Wi-Fi proxy settings on iOS and Android</li><li>Installing the CA certificate on mobile devices</li><li>Using the QR code feature for quick certificate download</li></ul><hr><h3 id="testing-error-handling" tabindex="-1"><a href="./testing-error-handling.html">Testing Error Handling</a> <a class="header-anchor" href="#testing-error-handling" aria-label="Permalink to &quot;[Testing Error Handling](./testing-error-handling)&quot;">​</a></h3><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 10 minutes</p><p>Verify that your application gracefully handles network errors, server failures, rate limiting, and timeouts. Use a combination of Block, Mock, and Delay rules to simulate failure conditions.</p><p><strong>What you will learn:</strong></p><ul><li>Blocking requests to test connection error handling</li><li>Returning 500 and 503 responses to test server error flows</li><li>Simulating rate limiting with 429 responses and Retry-After headers</li><li>Using delays to trigger client-side timeouts</li><li>Modifying responses on the fly with breakpoints</li></ul><hr><h3 id="simulating-slow-networks" tabindex="-1"><a href="./simulating-slow-networks.html">Simulating Slow Networks</a> <a class="header-anchor" href="#simulating-slow-networks" aria-label="Permalink to &quot;[Simulating Slow Networks](./simulating-slow-networks)&quot;">​</a></h3><p><strong>Difficulty:</strong> Beginner | <strong>Time:</strong> 10 minutes</p><p>Test how your application behaves on slow or unreliable connections. Use NectoProxy&#39;s built-in network conditioning presets to simulate everything from 2G mobile to WiFi, or create custom profiles.</p><p><strong>What you will learn:</strong></p><ul><li>Using the Network Conditioning panel</li><li>Selecting built-in presets (Slow 2G, 3G, 4G, DSL, WiFi, Offline)</li><li>Creating custom network profiles</li><li>Testing progressive loading and lazy-loading behavior</li><li>Combining global conditioning with per-URL throttle rules</li></ul><hr><h3 id="debugging-websockets" tabindex="-1"><a href="./debugging-websockets.html">Debugging WebSockets</a> <a class="header-anchor" href="#debugging-websockets" aria-label="Permalink to &quot;[Debugging WebSockets](./debugging-websockets)&quot;">​</a></h3><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 10 minutes</p><p>Inspect WebSocket connections and their individual frames. Learn how to find WebSocket traffic in the NectoProxy UI and analyze frame data, direction, opcodes, and timestamps.</p><p><strong>What you will learn:</strong></p><ul><li>Identifying WebSocket connections in the traffic list</li><li>Viewing individual WebSocket frames</li><li>Understanding frame direction, opcodes, and data formats</li><li>Filtering for WebSocket traffic</li><li>Troubleshooting common WebSocket issues</li></ul><hr><h3 id="chaining-proxies" tabindex="-1"><a href="./chaining-proxies.html">Chaining Proxies</a> <a class="header-anchor" href="#chaining-proxies" aria-label="Permalink to &quot;[Chaining Proxies](./chaining-proxies)&quot;">​</a></h3><p><strong>Difficulty:</strong> Advanced | <strong>Time:</strong> 10 minutes</p><p>Route NectoProxy&#39;s outbound traffic through an upstream proxy. Essential for corporate environments with mandatory HTTP proxies, or for routing through SOCKS5 tunnels.</p><p><strong>What you will learn:</strong></p><ul><li>Configuring HTTP/HTTPS upstream proxies</li><li>Configuring SOCKS4/SOCKS5 upstream proxies</li><li>Setting up proxy authentication</li><li>Creating bypass rules for internal domains</li><li>Common chaining scenarios (corporate proxy, SSH tunnel, Tor)</li></ul><hr><h3 id="exporting-importing-traffic" tabindex="-1"><a href="./exporting-traffic.html">Exporting &amp; Importing Traffic</a> <a class="header-anchor" href="#exporting-importing-traffic" aria-label="Permalink to &quot;[Exporting &amp; Importing Traffic](./exporting-traffic)&quot;">​</a></h3><p><strong>Difficulty:</strong> Beginner | <strong>Time:</strong> 5 minutes</p><p>Export captured traffic to HAR (HTTP Archive) files for sharing, archiving, or importing into other tools. Import HAR files from Chrome DevTools, Firefox, or other proxy tools.</p><p><strong>What you will learn:</strong></p><ul><li>Exporting a full session as a HAR file</li><li>Exporting selected entries only</li><li>Importing HAR files from other tools</li><li>Privacy considerations when sharing HAR files</li><li>Working with HAR files across different tools</li></ul><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before starting any tutorial, make sure you have:</p><ol><li><strong>NectoProxy installed</strong> -- Follow the <a href="/nectoproxy/guide/">installation guide</a> if you have not yet.</li><li><strong>NectoProxy running</strong> -- Start it with <code>nectoproxy start</code>.</li><li><strong>CA certificate installed</strong> -- Required for HTTPS interception. See the <a href="/nectoproxy/certificate/">certificate setup</a> guide.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Each tutorial is self-contained. You can jump to any tutorial that matches your current need -- there is no required reading order.</p></div>',49)])])}const h=e(n,[["render",a]]);export{p as __pageData,h as default};
